import json
recs = json.load(open("/online1/ycsc_chenkh/hitici_07/deepseek-harness/output_work/records.json"))
by = {}
for r in recs:
    by.setdefault(r.get('Portfolio key'), []).append(r)

CONTROLS = ["identity_crosswalk","operative_authority","current_operations","approval_and_capacity"]
keys = sorted(by.keys())
for k in keys:
    rs = sorted(by[k], key=lambda r: (r.get('Evidence role') or ''))
    print("="*100)
    print("KEY", k, "| subject:", rs[0].get('subject') if rs else '')
    for r in rs:
        role = r.get('Evidence role')
        if role in CONTROLS:
            print("  [%s] rec %s entity=%s ref=%s cur=%s" % (role, r.get('record_id'), r.get('Immutable entity'), r.get('Referenced revision'), r.get('Current revision')))
            print("      BODY:", (r.get('body') or '').strip())
